// ============================================================================
// MIL_STD_1553_apb: APB4 register wrapper around MIL_STD_1553_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/MIL_STD_1553.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/MIL_STD_1553.md
// ============================================================================
module MIL_STD_1553_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_a_p,
  output logic tx_a_n,
  output logic tx_b_p,
  output logic tx_b_n,
  input logic rx_a_p,
  input logic rx_a_n,
  input logic rx_b_p,
  input logic rx_b_n
);
  localparam logic [31:0] ID_VALUE = 32'h15530100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [17:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd18) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_cfg_half;
  logic          c_cfg_bc;
  logic [7:0]    c_cfg_resp_timeout;
  logic          c_host_rd;
  logic          c_host_wr;
  logic [10:0]   c_host_addr;
  logic [15:0]   c_host_wdata;
  logic [15:0]   c_host_rdata;
  logic [4:0]    c_cfg_rt_addr;
  logic          c_cfg_bcast_en;
  logic          c_cfg_sr;
  logic          c_cfg_busy;
  logic          c_cfg_ssf;
  logic          c_cfg_tf;
  logic [15:0]   c_cfg_vector;
  logic [15:0]   c_cfg_bit_word;
  logic          c_rt_msg;
  logic [15:0]   c_rt_msg_cmd;
  logic          c_rt_msg_bus;
  logic          c_rt_msg_err;
  logic [2:0]    c_rt_msg_why;
  logic          c_rt_msg_bcast;
  logic [5:0]    c_rt_msg_cnt;
  logic          c_mc_sync;
  logic          c_mc_selftest;
  logic          c_mc_reset;
  logic          c_mc_sync_data;
  logic [15:0]   c_mc_data;
  logic [1:0]    c_rt_tx_shut;
  logic          c_rt_tf_inh;
  logic          c_bc_start;
  logic [2:0]    c_bc_type;
  logic          c_bc_bus;
  logic [15:0]   c_bc_cmd1;
  logic [15:0]   c_bc_cmd2;
  logic          c_bc_busy;
  logic          c_bc_done;
  logic          c_bc_err_noresp;
  logic          c_bc_err_addr;
  logic          c_bc_err_word;
  logic          c_bc_err_wc;
  logic [15:0]   c_bc_stat1;
  logic [15:0]   c_bc_stat2;
  logic [5:0]    c_bc_cnt;
  MIL_STD_1553_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_half(c_cfg_half),
    .cfg_bc(c_cfg_bc),
    .cfg_resp_timeout(c_cfg_resp_timeout),
    .tx_a_p(tx_a_p),
    .tx_a_n(tx_a_n),
    .tx_b_p(tx_b_p),
    .tx_b_n(tx_b_n),
    .rx_a_p(rx_a_p),
    .rx_a_n(rx_a_n),
    .rx_b_p(rx_b_p),
    .rx_b_n(rx_b_n),
    .host_rd(c_host_rd),
    .host_wr(c_host_wr),
    .host_addr(c_host_addr),
    .host_wdata(c_host_wdata),
    .host_rdata(c_host_rdata),
    .cfg_rt_addr(c_cfg_rt_addr),
    .cfg_bcast_en(c_cfg_bcast_en),
    .cfg_sr(c_cfg_sr),
    .cfg_busy(c_cfg_busy),
    .cfg_ssf(c_cfg_ssf),
    .cfg_tf(c_cfg_tf),
    .cfg_vector(c_cfg_vector),
    .cfg_bit_word(c_cfg_bit_word),
    .rt_msg(c_rt_msg),
    .rt_msg_cmd(c_rt_msg_cmd),
    .rt_msg_bus(c_rt_msg_bus),
    .rt_msg_err(c_rt_msg_err),
    .rt_msg_why(c_rt_msg_why),
    .rt_msg_bcast(c_rt_msg_bcast),
    .rt_msg_cnt(c_rt_msg_cnt),
    .mc_sync(c_mc_sync),
    .mc_selftest(c_mc_selftest),
    .mc_reset(c_mc_reset),
    .mc_sync_data(c_mc_sync_data),
    .mc_data(c_mc_data),
    .rt_tx_shut(c_rt_tx_shut),
    .rt_tf_inh(c_rt_tf_inh),
    .bc_start(c_bc_start),
    .bc_type(c_bc_type),
    .bc_bus(c_bc_bus),
    .bc_cmd1(c_bc_cmd1),
    .bc_cmd2(c_bc_cmd2),
    .bc_busy(c_bc_busy),
    .bc_done(c_bc_done),
    .bc_err_noresp(c_bc_err_noresp),
    .bc_err_addr(c_bc_err_addr),
    .bc_err_word(c_bc_err_word),
    .bc_err_wc(c_bc_err_wc),
    .bc_stat1(c_bc_stat1),
    .bc_stat2(c_bc_stat2),
    .bc_cnt(c_bc_cnt)
  );

  // ---------------- registers ----------------
  logic [6:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [10:0] r_CTRL;   // 12'h014 CTRL
  logic [15:0] r_TIMING;   // 12'h018 TIMING
  logic [31:0] r_WORDS;   // 12'h01C WORDS
  logic [31:0] r_BC_CMD;   // 12'h020 BC_CMD
  logic [3:0] r_BC_CTRL;   // 12'h024 BC_CTRL
  logic [10:0] r_MEM_ADDR;   // 12'h028 MEM_ADDR
  logic [15:0] r_MEM_WDATA;   // 12'h02C MEM_WDATA
  logic [2:0] p_CMD;   // 12'h030 CMD (pulses)
  logic [27:0] h_RT_MSG;   // 12'h044 RT_MSG holding register
  logic avail_RT_MSG;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 11'h2;
      r_TIMING <= 16'h1C19;
      r_WORDS <= 32'h0;
      r_BC_CMD <= 32'h0;
      r_BC_CTRL <= 4'h0;
      r_MEM_ADDR <= 11'h0;
      r_MEM_WDATA <= 16'h0;
      p_CMD <= '0;
      h_RT_MSG <= '0;
      avail_RT_MSG <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[6:0] & wmask[6:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[6]) r_TIMING <= (r_TIMING & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[7]) r_WORDS <= (r_WORDS & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_BC_CMD <= (r_BC_CMD & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_BC_CTRL <= (r_BC_CTRL & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[10]) r_MEM_ADDR <= (r_MEM_ADDR & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[11]) r_MEM_WDATA <= (r_MEM_WDATA & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_CMD <= (wr && hit[12]) ? PWDATA[2:0] & wmask[2:0] : '0;
      if (c_rt_msg && (!avail_RT_MSG || (rd && hit[17]))) begin
        h_RT_MSG[15:0] <= c_rt_msg_cmd[15:0];
        h_RT_MSG[16:16] <= c_rt_msg_bus;
        h_RT_MSG[17:17] <= c_rt_msg_err;
        h_RT_MSG[20:18] <= c_rt_msg_why[2:0];
        h_RT_MSG[21:21] <= c_rt_msg_bcast;
        h_RT_MSG[27:22] <= c_rt_msg_cnt[5:0];
        avail_RT_MSG <= 1'b1;
      end else if (rd && hit[17]) avail_RT_MSG <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_bc = r_CTRL[0:0];
  assign c_cfg_bcast_en = r_CTRL[1:1];
  assign c_cfg_rt_addr = r_CTRL[6:2];
  assign c_cfg_sr = r_CTRL[7:7];
  assign c_cfg_busy = r_CTRL[8:8];
  assign c_cfg_ssf = r_CTRL[9:9];
  assign c_cfg_tf = r_CTRL[10:10];
  assign c_cfg_half = r_TIMING[7:0];
  assign c_cfg_resp_timeout = r_TIMING[15:8];
  assign c_cfg_vector = r_WORDS[15:0];
  assign c_cfg_bit_word = r_WORDS[31:16];
  assign c_bc_cmd1 = r_BC_CMD[15:0];
  assign c_bc_cmd2 = r_BC_CMD[31:16];
  assign c_bc_type = r_BC_CTRL[2:0];
  assign c_bc_bus = r_BC_CTRL[3:3];
  assign c_host_addr = r_MEM_ADDR[10:0];
  assign c_host_wdata = r_MEM_WDATA[15:0];
  assign c_bc_start = p_CMD[0:0];
  assign c_host_wr = p_CMD[1:1];
  assign c_host_rd = p_CMD[2:2];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_bc_done;
    irq_set[1] = c_mc_sync;
    irq_set[2] = c_mc_selftest;
    irq_set[3] = c_mc_reset;
    irq_set[4] = c_mc_sync_data;
    irq_set[5] = c_rt_msg & (~avail_RT_MSG | (rd & hit[17]));
    irq_set[6] = c_rt_msg & avail_RT_MSG & ~(rd & hit[17]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {avail_RT_MSG};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_TIMING);
      10'd7: apb_rdata = 32'(r_WORDS);
      10'd8: apb_rdata = 32'(r_BC_CMD);
      10'd9: apb_rdata = 32'(r_BC_CTRL);
      10'd10: apb_rdata = 32'(r_MEM_ADDR);
      10'd11: apb_rdata = 32'(r_MEM_WDATA);
      10'd13: apb_rdata = 32'({c_host_rdata});
      10'd14: apb_rdata = 32'({c_bc_cnt, c_bc_err_wc, c_bc_err_word, c_bc_err_addr, c_bc_err_noresp, c_bc_busy});
      10'd15: apb_rdata = 32'({c_bc_stat2, c_bc_stat1});
      10'd16: apb_rdata = 32'({c_mc_data, c_rt_tf_inh, c_rt_tx_shut});
      10'd17: apb_rdata = 32'(h_RT_MSG);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
